content:
:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;

  color-scheme: light dark;
  color: rgba(255, 255, 255, 0.87);
  background-color: #242424;

  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  display: flex;
  place-items: center;
  justify-content: center;
  min-width: 320px;
  min-height: 100vh;
  background: #1a1a1a;
}

* {
  box-sizing: border-box;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 1rem;
  max-width: 480px;
  width: 100%;
  margin: 0 auto;
  user-select: none;
}

.title {
  font-size: 2rem;
  font-weight: bold;
  margin-bottom: 0.5rem;
  color: #4ade80;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.3);
}

.score-board {
  display: flex;
  gap: 1.5rem;
  font-size: 1.1rem;
  margin-bottom: 1rem;
  background: #2a2a2a;
  padding: 0.5rem 1rem;
  border-radius: 8px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  border: 1px solid #333;
}

.score-board span {
  font-weight: bold;
  color: #f3f4f6;
}

.game-board {
  display: grid;
  grid-template-columns: repeat(20, 1fr);
  grid-template-rows: repeat(20, 1fr);
  width: 320px;
  height: 320px;
  background-color: #111;
  border: 4px solid #374151;
  border-radius: 8px;
  position: relative;
  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.3);
}

.cell {
  width: 100%;
  height: 100%;
}

.snake {
  background-color: #4ade80;
  border-radius: 3px;
  box-shadow: inset 0 0 2px rgba(0, 0, 0, 0.5);
}

.food {
  background-color: #f87171;
  border-radius: 50%;
  box-shadow: 0 0 8px #f87171;
  animation: pulse 1s infinite alternate;
}

@keyframes pulse {
  0% { transform: scale(0.9); }
  100% { transform: scale(1.1); }
}

.controls {
  margin-top: 1.5rem;
  display: flex;
  justify-content: center;
  width: 100%;
}

.d-pad {
  display: grid;
  grid-template-columns: repeat(3, 60px);
  grid-template-rows: repeat(2, 60px);
  gap: 8px;
  justify-items: center;
  align-items: center;
}

.btn-dir {
  background-color: #374151;
  color: white;
  border: none;
  border-radius: 12px;
  font-size: 1.25rem;
  font-weight: bold;
  cursor: pointer;
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.2);
  transition: background-color 0.1s, transform 0.1s;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.btn-dir:active {
  background-color: #4b5563;
  transform: scale(0.95);
}

/* 十字キーの配置 */
.btn-dir:nth-child(1) { /* UP */
  grid-column: 2;
  grid-row: 1;
}

.btn-dir:nth-child(2) { /* LEFT */
  grid-column: 1;
  grid-row: 2;
}

.btn-dir:nth-child(3) { /* DOWN */
  grid-column: 2;
  grid-row: 2;
}

.btn-dir:nth-child(4) { /* RIGHT */
  grid-column: 3;
  grid-row: 2;
}

.game-over-modal {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.75);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  animation: fadeIn 0.2s ease-out;
  z-index: 10;
}

.game-over-modal h2 {
  color: #f87171;
  font-size: 2rem;
  margin-bottom: 1rem;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5);
}

.btn-primary {
  background-color: #22c55e;
  color: white;
  border: none;
  padding: 0.75rem 1.5rem;
  font-size: 1.1rem;
  font-weight: bold;
  border-radius: 8px;
  cursor: pointer;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.2);
  transition: background-color 0.1s, transform 0.1s;
}

.btn-primary:hover {
  background-color: #16a34a;
}

.btn-primary:active {
  transform: scale(0.95);
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@media (max-width: 360px) {
  .game-board {
    width: 280px;
    height: 280px;
  }
}

export interface Point {
  x: number;
  y: number;
}

export type Direction = 'UP' | 'DOWN' | 'LEFT' | 'RIGHT';

export type GameStatus = 'IDLE' | 'PLAYING' | 'GAME_OVER';

import { Point } from './types';

interface GameBoardProps {
  snake: Point[];
  food: Point;
  gameStatus: string;
  score: number;
  onRestart: () => void;
}

export default function GameBoard({ snake, food, gameStatus, score, onRestart }: GameBoardProps) {
  const GRID_SIZE = 20;
  const cells = [];

  const isSnakeCell = (x: number, y: number) => {
    return snake.some(segment => segment.x === x && segment.y === y);
  };

  const isFoodCell = (x: number, y: number) => {
    return food.x === x && food.y === y;
  };

  for (let y = 0; y < GRID_SIZE; y++) {
    for (let x = 0; x < GRID_SIZE; x++) {
      let className = 'cell';
      if (isSnakeCell(x, y)) {
        className += ' snake';
      } else if (isFoodCell(x, y)) {
        className += ' food';
      }
      cells.push(<div key={`${x}-${y}`} className={className} />);
    }
  }

  return (
    <div className="game-board">
      {cells}
      {gameStatus === 'GAME_OVER' && (
        <div className="game-over-modal">
          <h2>ゲームオーバー</h2>
          <p style={{ marginBottom: '1rem', color: '#d1d5db' }}>スコア: {score}</p>
          <button className="btn-primary" onClick={onRestart}>
            やり直す
          </button>
        </div>
      )}
    </div>
  );
}

import { Direction } from './types';

interface ControlsProps {
  onDirectionChange: (direction: Direction) => void;
}

export default function Controls({ onDirectionChange }: ControlsProps) {
  return (
    <div className="controls">
      <div className="d-pad">
        <button className="btn-dir" onClick={() => onDirectionChange('UP')}>
          ▲
        </button>
        <button className="btn-dir" onClick={() => onDirectionChange('LEFT')}>
          ◀
        </button>
        <button className="btn-dir" onClick={() => onDirectionChange('DOWN')}>
          ▼
        </button>
        <button className="btn-dir" onClick={() => onDirectionChange('RIGHT')}>
          ▶
        </button>
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { Point, Direction, GameStatus } from './types';
import GameBoard from './GameBoard';
import Controls from './Controls';
import './index.css';

const GRID_SIZE = 20;

const INITIAL_SNAKE: Point[] = [
  { x: 10, y: 10 },
  { x: 10, y: 11 },
  { x: 10, y: 12 },
];

const INITIAL_FOOD: Point = { x: 5, y: 5 };

export default function App() {
  const [snake, setSnake] = useState<Point[]>(INITIAL_SNAKE);
  const [food, setFood] = useState<Point>(INITIAL_FOOD);
  const [direction, setDirection] = useState<Direction>('UP');
  const [gameStatus, setGameStatus] = useState<GameStatus>('IDLE');
  const [score, setScore] = useState<number>(0);
  const [highScore, setHighScore] = useState<number>(() => {
    const saved = localStorage.getItem('snake_highscore');
    return saved ? parseInt(saved, 10) : 0;
  });

  const directionRef = useRef<Direction>(direction);
  directionRef.current = direction;

  const generateFood = useCallback((currentSnake: Point[]): Point => {
    let newFood: Point;
    while (true) {
      newFood = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE),
      };
      const collides = currentSnake.some(segment => segment.x === newFood.x && segment.y === newFood.y);
      if (!collides) break;
    }
    return newFood;
  }, []);

  const handleDirectionChange = useCallback((newDir: Direction) => {
    const current = directionRef.current;
    if (
      (newDir === 'UP' && current === 'DOWN') ||
      (newDir === 'DOWN' && current === 'UP') ||
      (newDir === 'LEFT' && current === 'RIGHT') ||
      (newDir === 'RIGHT' && current === 'LEFT')
    ) {
      return;
    }
    if (gameStatus === 'IDLE') {
      setGameStatus('PLAYING');
    }
    setDirection(newDir);
  }, [gameStatus]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (['ArrowUp', 'KeyW'].includes(e.code)) {
        e.preventDefault();
        handleDirectionChange('UP');
      } else if (['ArrowDown', 'KeyS'].includes(e.code)) {
        e.preventDefault();
        handleDirectionChange('DOWN');
      } else if (['ArrowLeft', 'KeyA'].includes(e.code)) {
        e.preventDefault();
        handleDirectionChange('LEFT');
      } else if (['ArrowRight', 'KeyD'].includes(e.code)) {
        e.preventDefault();
        handleDirectionChange('RIGHT');
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleDirectionChange]);

  const restartGame = () => {
    const newSnake = INITIAL_SNAKE;
    setSnake(newSnake);
    setFood(generateFood(newSnake));
    setDirection('UP');
    setGameStatus('PLAYING');
    setScore(0);
  };

  useEffect(() => {
    if (gameStatus !== 'PLAYING') return;

    const intervalId = setInterval(() => {
      setSnake(prevSnake => {
        const head = { ...prevSnake[0] };

        switch (directionRef.current) {
          case 'UP':
            head.y -= 1;
            break;
          case 'DOWN':
            head.y += 1;
            break;
          case 'LEFT':
            head.x -= 1;
            break;
          case 'RIGHT':
            head.x += 1;
            break;
        }

        // 壁との衝突
        if (head.x < 0 || head.x >= GRID_SIZE || head.y < 0 || head.y >= GRID_SIZE) {
          setGameStatus('GAME_OVER');
          return prevSnake;
        }

        // 自分自身との衝突
        if (prevSnake.some(segment => segment.x === head.x && segment.y === head.y)) {
          setGameStatus('GAME_OVER');
          return prevSnake;
        }

        const newSnake = [head, ...prevSnake];

        // エサを食べたか
        if (head.x === food.x && head.y === food.y) {
          const newScore = score + 10;
          setScore(newScore);
          if (newScore > highScore) {
            setHighScore(newScore);
            localStorage.setItem('snake_highscore', newScore.toString());
          }
          setFood(generateFood(newSnake));
        } else {
          newSnake.pop();
        }

        return newSnake;
      });
    }, 120);

    return () => clearInterval(intervalId);
  }, [gameStatus, food, score, highScore, generateFood]);

  return (
    <div className="app-container">
      <h1 className="title">スネークゲーム</h1>
      <div className="score-board">
        <div>スコア: <span>{score}</span></div>
        <div>ハイスコア: <span>{highScore}</span></div>
      </div>
      <GameBoard
        snake={snake}
        food={food}
        gameStatus={gameStatus}
        score={score}
        onRestart={restartGame}
      />
      <Controls onDirectionChange={handleDirectionChange} />
    </div>
  );
}
